BEGIN TRANSACTION;
CREATE TABLE cache (key VARCHAR(255) PRIMARY KEY, value MEDIUMTEXT NOT NULL, expiration INTEGER NOT NULL);
CREATE TABLE cache_locks (key VARCHAR(255) PRIMARY KEY, owner VARCHAR(255) NOT NULL, expiration INTEGER NOT NULL);
CREATE TABLE failed_jobs (id INTEGER PRIMARY KEY AUTOINCREMENT, uuid VARCHAR(255) NOT NULL UNIQUE, connection TEXT NOT NULL, queue TEXT NOT NULL, payload TEXT NOT NULL, exception TEXT NOT NULL, failed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE job_batches (id VARCHAR(255) PRIMARY KEY, name VARCHAR(255) NOT NULL, total_jobs INTEGER NOT NULL, pending_jobs INTEGER NOT NULL, failed_jobs INTEGER NOT NULL, failed_job_ids TEXT NOT NULL, options MEDIUMTEXT, cancelled_at INTEGER, created_at INTEGER NOT NULL, finished_at INTEGER);
CREATE TABLE jobs (id INTEGER PRIMARY KEY AUTOINCREMENT, queue VARCHAR(255) NOT NULL, payload TEXT NOT NULL, attempts TINYINT NOT NULL, reserved_at INTEGER, available_at INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE menus (id CHAR(36) PRIMARY KEY, resto_id CHAR(36) NOT NULL, nama VARCHAR(255) NOT NULL, kategori VARCHAR(255) NOT NULL, harga INTEGER NOT NULL, foto VARCHAR(255), tersedia BOOLEAN NOT NULL DEFAULT 1, created_at DATETIME, updated_at DATETIME, FOREIGN KEY(resto_id) REFERENCES restos(id) ON DELETE CASCADE);
CREATE TABLE migrations (id INTEGER PRIMARY KEY AUTOINCREMENT, migration VARCHAR(255) NOT NULL, batch INTEGER NOT NULL);
CREATE TABLE password_reset_tokens (email VARCHAR(255) PRIMARY KEY, token VARCHAR(255) NOT NULL, created_at DATETIME);
CREATE TABLE reservasi_items (id CHAR(36) PRIMARY KEY, reservasi_id CHAR(36) NOT NULL, menu_id CHAR(36) NOT NULL, jumlah INTEGER NOT NULL, harga_satuan INTEGER NOT NULL, created_at DATETIME, updated_at DATETIME, FOREIGN KEY(reservasi_id) REFERENCES reservasis(id) ON DELETE CASCADE, FOREIGN KEY(menu_id) REFERENCES menus(id));
CREATE TABLE reservasis (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, resto_id CHAR(36) NOT NULL, tanggal DATE NOT NULL, jam TIME NOT NULL, jumlah_orang INTEGER NOT NULL, catatan TEXT, status VARCHAR(255) NOT NULL DEFAULT 'menunggu', total_harga INTEGER NOT NULL DEFAULT 0, dp_nominal INTEGER NOT NULL DEFAULT 0, bukti_dp VARCHAR(255), status_dp VARCHAR(255) NOT NULL DEFAULT 'belum_bayar', status_pembayaran VARCHAR(255) NOT NULL DEFAULT 'belum_lunas', alasan_penolakan TEXT, created_at DATETIME, updated_at DATETIME, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(resto_id) REFERENCES restos(id) ON DELETE CASCADE);
CREATE TABLE restos (id CHAR(36) PRIMARY KEY, pemilik_id CHAR(36) NOT NULL, nama VARCHAR(255) NOT NULL, alamat TEXT NOT NULL, kota VARCHAR(255) NOT NULL, kapasitas INTEGER NOT NULL, jam_buka TIME NOT NULL, jam_tutup TIME NOT NULL, fasilitas TEXT, foto VARCHAR(255), dp_persen INTEGER NOT NULL DEFAULT 30, nama_bank VARCHAR(255), no_rekening VARCHAR(255), atas_nama VARCHAR(255), is_active BOOLEAN NOT NULL DEFAULT 1, created_at DATETIME, updated_at DATETIME, FOREIGN KEY(pemilik_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE sessions (id VARCHAR(255) PRIMARY KEY, user_id CHAR(36), ip_address VARCHAR(45), user_agent TEXT, payload TEXT NOT NULL, last_activity INTEGER NOT NULL);
CREATE TABLE users (id CHAR(36) PRIMARY KEY, name VARCHAR(255) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, no_hp VARCHAR(20), password VARCHAR(255) NOT NULL, role VARCHAR(255) NOT NULL DEFAULT 'pelanggan', is_active BOOLEAN NOT NULL DEFAULT 1, remember_token VARCHAR(100), created_at DATETIME, updated_at DATETIME);
CREATE INDEX sessions_user_id_index ON sessions(user_id);
CREATE INDEX sessions_last_activity_index ON sessions(last_activity);
CREATE INDEX jobs_queue_index ON jobs(queue);
DELETE FROM "sqlite_sequence";
COMMIT;
